    global BEST_MODEL, BEST_MODEL_NAME, BEST_MODEL_TYPE
    with open('/app/models/best_model.pkl', 'rb') as f:
        model = pickle.load(f)
    BEST_MODEL = model
    # Determine model name and type from the class name
    class_name = model.__class__.__name__
    if 'RandomForest' in class_name:
        BEST_MODEL_NAME = "random_forest"
        BEST_MODEL_TYPE = "RandomForestRegressor"
    elif 'Ridge' in class_name:
        BEST_MODEL_NAME = "ridge"
        BEST_MODEL_TYPE = "Ridge"
    elif 'LinearRegression' in class_name:
        BEST_MODEL_NAME = "linear_regression"
        BEST_MODEL_TYPE = "LinearRegression"
    else:
        BEST_MODEL_NAME = "unknown"
        BEST_MODEL_TYPE = class_name
    return model

# Use lifespan context manager for startup event (FastAPI best practice)
from contextlib import asynccontextmanager

@asynccontextmanager
async def lifespan(app: FastAPI):
    """Handle application startup and shutdown."""
    # Startup: load the model
    load_model()
    print(f"Model loaded: {BEST_MODEL_NAME} ({BEST_MODEL_TYPE})")
    yield

app = FastAPI(lifespan=lifespan)

# Pydantic models for request/response
class PredictRequest(BaseModel):
    features: list

class PredictResponse(BaseModel):
    prediction: float
    model_name: str

class HealthResponse(BaseModel):
    status: str
    model_loaded: bool

class ModelInfoResponse(BaseModel):
    model_name: str
    model_type: str
    features_count: int

class PredictBatchRequest(BaseModel):
    features_list: list

class PredictBatchResponse(BaseModel):
    predictions: list
    model_name: str
    count: int

@app.get("/health")
def health_check() -> HealthResponse:
    """Health check endpoint"""
    return HealthResponse(
        status="healthy",
        model_loaded=BEST_MODEL is not None
    )

@app.get("/model-info")
def model_info() -> ModelInfoResponse:
    """Model information endpoint"""
    if BEST_MODEL is None:
        return ModelInfoResponse(
            model_name="unknown",
            model_type="unknown",
            features_count=0
        )
    return ModelInfoResponse(
        model_name=BEST_MODEL_NAME,
        model_type=BEST_MODEL_TYPE,
        features_count=8
    )

@app.post("/predict")
def predict(request: PredictRequest) -> PredictResponse:
    """
    Predict house price for a single sample
    Input: {"features": [float, float, float, float, float, float, float, float]}
    Output: {"prediction": float, "model_name": string}
    """
    if BEST_MODEL is None:
        return {"error": "Model not loaded"}

    # Validate input has exactly 8 features
    if len(request.features) != 8:
        return {"error": "Exactly 8 features required"}

    prediction = BEST_MODEL.predict([request.features])[0]
    return PredictResponse(
        prediction=float(prediction),
        model_name=BEST_MODEL_NAME
    )

@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest) -> PredictBatchResponse:
    """
    Predict house prices for multiple samples
    Input: {"features_list": [[float, ...], [float, ...], ...]}
    Output: {"predictions": [float, ...], "model_name": string, "count": int}
    """
    if BEST_MODEL is None:
        return {"error": "Model not loaded"}

    # Validate each sample has exactly 8 features
    for i, features in enumerate(request.features_list):
        if len(features) != 8:
            return {"error": f"Sample {i} must have exactly 8 features"}

    predictions = BEST_MODEL.predict(request.features_list)
    return PredictBatchResponse(
        predictions=[float(p) for p in predictions],
        model_name=BEST_MODEL_NAME,
        count=len(predictions)
    )
